<?php
if(!defined('ABSPATH'))exit;
function bsktv_feature_box(){add_meta_box('bsktv_flags','推薦設定','bsktv_flags_render','post','side','default');}add_action('add_meta_boxes','bsktv_feature_box');
function bsktv_flags_render($post){wp_nonce_field('bsktv_flags_save','bsktv_flags_nonce');echo '<p><label><input type="checkbox" name="bsktv_featured" value="1" '.checked(get_post_meta($post->ID,'bsktv_featured',true),'1',false).'> 編輯推薦</label></p><p><label><input type="checkbox" name="bsktv_home_featured" value="1" '.checked(get_post_meta($post->ID,'bsktv_home_featured',true),'1',false).'> 首頁精選</label></p>';}function bsktv_flags_save($id){if(!isset($_POST['bsktv_flags_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['bsktv_flags_nonce'])),'bsktv_flags_save'))return;if(defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE)return;if(wp_is_post_revision($id)||!current_user_can('edit_post',$id))return;update_post_meta($id,'bsktv_featured',isset($_POST['bsktv_featured'])?'1':'0');update_post_meta($id,'bsktv_home_featured',isset($_POST['bsktv_home_featured'])?'1':'0');}add_action('save_post_post','bsktv_flags_save');
function bsktv_track_views(){if(!is_singular('post')||is_admin()||wp_doing_ajax()||is_preview()||current_user_can('edit_posts'))return;$id=get_queried_object_id();if(!$id||get_post_status($id)!=='publish')return;$status=get_post_meta($id,'bsktv_status',true);if($status!==''&&$status!=='active')return;$cookie='bsktv_viewed_'.$id;if(isset($_COOKIE[$cookie]))return;$expires=time()+1800;$path=defined('COOKIEPATH')&&COOKIEPATH?COOKIEPATH:'/';$secure=is_ssl();setcookie($cookie,'1',array('expires'=>$expires,'path'=>$path,'secure'=>$secure,'httponly'=>true,'samesite'=>'Lax'));$_COOKIE[$cookie]='1';global $wpdb;$table=$wpdb->postmeta;$meta_id=$wpdb->get_var($wpdb->prepare("SELECT meta_id FROM {$table} WHERE post_id=%d AND meta_key=%s LIMIT 1",$id,'bsktv_views'));if($meta_id){$wpdb->query($wpdb->prepare("UPDATE {$table} SET meta_value=CAST(meta_value AS UNSIGNED)+1 WHERE meta_id=%d",$meta_id));}else{add_post_meta($id,'bsktv_views','1',true);}}add_action('template_redirect','bsktv_track_views');
function bsktv_line_clicks($id=null){return (int)get_post_meta($id?:get_the_ID(),'bsktv_line_clicks',true);}
